L.STRINGS = {
	["120 Merchant's Favor"] = "120 Faveurs du marchand",
	["1200 Merchant's Favor"] = "1200 Faveurs du marchand",
	["1500 Merchant's Favor"] = "1500 Faveurs du marchand",
	["180 Merchant's Favor"] = "180 Faveurs du marchand",
	["200 Merchant's Favor"] = "200 Faveurs du marchand",
	["240 Merchant's Favor"] = "240 Faveurs du marchand",
	["270 Merchant's Favor"] = "270 Faveurs du marchand",
	["360 Merchant's Favor"] = "360 Faveurs du marchand",
	["60 Merchant's Favor"] = "60 Faveurs du marchand",
	["6000 Merchant's Favor"] = "6000 Faveurs du marchand",
	["90 Merchant's Favor"] = "90 Faveurs du marchand",
	["A 1.5-second cast: a 3-minute curse that hurts the player now and then when they attack. Remove it."] = "Incantation de 1.5 seconde : une malédiction de 3 minutes qui blesse le joueur de temps en temps lorsqu'il attaque. Retirez-la.",
	["A 2-second cast, then for 6 seconds arcane energy hits everyone within 25 yards every 2 seconds, for about 140 damage each time. Ranged players, stay beyond 25 yards; melee, step out during the cast."] = "Incantation de 2 secondes, puis, pendant 6 secondes, de l'énergie arcanique frappe tout le monde à moins de 25 mètres toutes les 2 secondes, pour environ 140 points de dégâts à chaque fois. Joueurs à distance, restez au-delà de 25 mètres ; joueurs de mêlée, éloignez-vous pendant l'incantation.",
	["A 2-second cast: a hit, then Nature damage for a minute. Cure the poison."] = "Incantation de 2 secondes : un coup, puis des dégâts de Nature pendant une minute. Retirez le poison.",
	["A 2-second cast: arcane power drains up to 200 mana from everyone within 45 yards of him."] = "Incantation de 2 secondes : une énergie arcanique draine jusqu'à 200 points de mana à tous ceux qui se trouvent à moins de 45 mètres de lui.",
	["A 3-second Shadow bolt on the tank, over and over. Interrupt it."] = "Un trait d'Ombre de 3 secondes sur le tank, encore et encore. Interrompez-le.",
	["A Binding Contract"] = "Un contrat contraignant",
	["A Blackrock orc who can be found in one of four cells."] = "Un orc rochenoire, présent dans l'une de quatre cellules.",
	["A Broken Trap"] = "Un piège cassé",
	["A Crumpled Up Note"] = "Une note chiffonnée",
	["A Dark Iron dwarf held for his part in the Thandol Span attacks."] = "Un nain sombrefer détenu pour son rôle dans les attaques du viaduc de Thandol.",
	["A Dynamite Plan"] = "Un plan à la dynamite",
	["A Fanglord who turns into a serpent partway through the fight."] = "Un seigneur du Croc qui se transforme en serpent en cours de combat.",
	["A Fine Mess"] = "Un beau gâchis",
	["A Frightened Request"] = "Une requête apeurée",
	["A Green Sample"] = "Un échantillon vert",
	["A Host of Evil"] = "Une armée maléfique",
	["A Reliquary of Purity"] = "Un reliquaire de pureté",
	["A Searing Blade warlock; clear the cultists around him first."] = "Un démoniste de la Lame ardente ; éliminez d'abord les cultistes qui l'entourent.",
	["A Shred of Hope"] = "Une lueur d'espoir",
	["A Sign of Hope"] = "Un signe d'espoir",
	["A Stone Rumbler fights at his side; interrupt his Lightning Bolt."] = "Un grondeur de pierre combat à ses côtés ; interrompez son Éclair.",
	["A Stone Rumbler stands with him and fights at his side."] = "Un grondeur de pierre l'accompagne et combat à ses côtés.",
	["A Taste of Flame"] = "Un avant-goût des flammes",
	["A Titan dig site above Whelgar's Excavation, caught out of time, where the Titans' constructs answer to no one now. Inside: the Lost Marsh, Stalker's Thicket, the Site of the Guardian and the Lost Dig Site."] = "Un chantier de fouilles titan au-dessus du site d'excavation de Whelgar, figé hors du temps, où les créations des Titans n'obéissent plus à personne. À l'intérieur : le Marais perdu, le Fourré du traqueur, le Site du Gardien et le Site de fouilles perdu.",
	["A Titan vault buried under the Badlands, where Dark Iron dwarves and troggs dig for the secrets of the earthen, and the stone keeper Archaedas guards the deepest hall."] = "Une chambre forte des Titans enfouie sous les Terres ingrates. Nains sombrefer et troggs y creusent pour percer les secrets des terrestres, et le gardien de pierre Archaedas veille sur la salle la plus profonde.",
	["A Twilight's Hammer shaman patrolling the tunnels."] = "Un chaman du Marteau du crépuscule qui patrouille dans les tunnels.",
	["A Vengeful Fate"] = "Un destin vengeur",
	["A dust storm hits the whole group now and then, and he slows the tank."] = "De temps en temps, une tempête de poussière frappe tout le groupe, et il ralentit le tank.",
	["A fallen paladin who heals himself and shields himself from harm."] = "Un paladin déchu qui se soigne et se protège des dégâts.",
	["A felguard standing in the middle of the lava lake, and the hardest-hitting boss here."] = "Un gangregarde posté au milieu du lac de lave, et le boss qui frappe le plus fort ici.",
	["A giant turtle in the first great pool."] = "Une tortue géante dans le premier grand bassin.",
	["A giant turtle that will not attack first; killing him is optional."] = "Une tortue géante qui n'attaque jamais en premier ; ce combat est facultatif.",
	["A heavy blow that knocks the tank back."] = "Un coup puissant qui repousse le tank.",
	["A heavy swing at everyone in front of him. Only the tank should stand there."] = "Un coup puissant qui touche tous ceux qui se trouvent devant lui. Seul le tank doit se tenir là.",
	["A hidden boss you summon. Take the Black Tome from Archmage Arugal's table in Shadowfang Keep after his kill, and turn it into the Tome of Dalaran at the Leyline Focus, a blue crystal in a back room at Ambermill in Silverpine Forest."] = "Un boss caché que vous invoquez. Prenez le Tome noir sur la table de l'archimage Arugal, au donjon d'Ombrecroc, une fois Arugal vaincu, puis transformez-le en Tome de Dalaran au Foyer de ligne tellurique, un cristal bleu dans une arrière-salle de Moulin-de-l'Ambre, dans la forêt des Pins-Argentés.",
	["A hidden elite you summon yourself."] = "Une élite cachée, que vous invoquez vous-même.",
	["A huge violet raptor, the leader of Stalker's Thicket."] = "Un énorme raptor violet, chef du Fourré du traqueur.",
	["A large health pool"] = "Beaucoup de points de vie",
	["A lightning bolt that jumps to a second player. Interrupt it."] = "Un éclair qui rebondit sur un second joueur. Interrompez-le.",
	["A mage or a druid can remove his Call of the Grave before it goes off. He fears, and drains two players below half health."] = "Un mage ou un druide peut dissiper son Appel de la tombe avant qu'il ne se déclenche. Il inflige la peur et, sous la moitié de ses points de vie, draine deux joueurs.",
	["A mage trainer in a capital"] = "Un maître des mages dans une capitale",
	["A magic debuff on the tank: around 65 Arcane damage every 2 seconds for 10 seconds. Dispel it."] = "Un affaiblissement magique sur le tank : environ 65 points de dégâts d'Arcanes toutes les 2 secondes pendant 10 secondes. Dissipez-le.",
	["A magic dispel removes his Shadow Word: Pain."] = "Une dissipation de la magie supprime son Mot de l'ombre : Douleur.",
	["A massive plant creature; optional."] = "Une énorme créature végétale ; facultatif.",
	["A murloc chieftain in his shrine. His followers run for help when they are low on health, so finish them off."] = "Un chef murloc dans son sanctuaire. Ses fidèles s'enfuient chercher de l'aide quand leur vie est basse : achevez-les.",
	["A naga sorceress in a side cavern off the pool; optional."] = "Une ensorceleuse naga dans une caverne latérale du bassin ; facultative.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Jordan's Smithing Hammer, picked up from Jordan's Hammer in the courtyard. The rest: Whitestone Oak Lumber in the Deadmines, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "Une quête de paladin pour les humains et les nains, dont les éléments se trouvent en plusieurs endroits. Ici : le Marteau de forgeron de Jordan, à ramasser sur le Marteau de Jordan dans la cour. Le reste : le Bois de chêne de Pierreblanche dans les Mortemines, la Gemme de Kor dans les Profondeurs de Brassenoire et la cargaison de minerai de Jordan au Loch Modan.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Whitestone Oak Lumber, which the Goblin Woodcarvers drop. The rest: Jordan's Smithing Hammer in Shadowfang Keep, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "Une quête de paladin pour les humains et les nains, dont les éléments se trouvent à plusieurs endroits. Ici : le Bois de chêne de Pierreblanche, sur les Sculpteurs sur bois gobelins. Le reste : le Marteau de forgeron de Jordan au Donjon d'Ombrecroc, la Gemme de Kor dans les Profondeurs de Brassenoire et la cargaison de minerai de Jordan au Loch Modan.",
	["A patrol"] = "Une patrouille",
	["A pillar of flame where a player stands (3-second cast): Fire damage, then more every 3 seconds for 9 seconds. Step out of it."] = "Une colonne de flammes sous un joueur (incantation de 3 secondes) : dégâts de Feu, puis d'autres toutes les 3 secondes pendant 9 secondes. Sortez-en.",
	["A player takes more Physical damage for 10 minutes (2-second cast). A mage or a druid can remove it."] = "Un joueur subit davantage de dégâts physiques pendant 10 minutes (incantation de 2 secondes). Un mage ou un druide peut l'enlever.",
	["A priest or a shaman can remove his Bloodlust."] = "Un prêtre ou un chaman peut dissiper sa Furie sanguinaire.",
	["A quilboar geomancer close to the Kraul's entrance."] = "Un géomancien huran, près de l'entrée du Kraal.",
	["A raid new in WoW: Forever, on Mount Hyjal. Its bosses and loot are not known yet."] = "Un nouveau raid de WoW: Forever, sur le mont Hyjal. Ses boss et son butin ne sont pas encore connus.",
	["A raid new in WoW: Forever. Its bosses and loot are not known yet."] = "Un nouveau raid de WoW: Forever. Ses boss et son butin ne sont pas encore connus.",
	["A rare bat in a small recess of the bat cave near Charlga Razorflank: not every run meets it."] = "Une chauve-souris rare, dans un petit renfoncement de la grotte aux chauves-souris près de Charlga Trancheflanc : on ne la croise pas à chaque passage.",
	["A rare bat, not there on every run. When it is, it waits in a small recess in the wall of the bat cave near Charlga Razorflank."] = "Une chauve-souris rare, pas présente à chaque passage. Quand elle est là, elle attend dans un petit renfoncement de la paroi de la grotte aux chauves-souris, près de Charlga Trancheflanc.",
	["A rare spawn: not every run meets him."] = "Un monstre rare : on ne le croise pas à chaque passage.",
	["A rare spawn: not every run meets him. At 15% health he runs for help."] = "Un monstre rare : il n'apparaît pas à chaque passage. À 15 % de points de vie, il s'enfuit chercher de l'aide.",
	["A rare. A Stone Rumbler fights with him; interrupt his Lightning Bolt, and finish him before he runs for help at 15% health."] = "Un monstre rare. Un Grondeur de pierre combat à ses côtés ; interrompez son Éclair et achevez-le avant qu'il ne s'enfuie chercher de l'aide à 15 % de points de vie.",
	["A rare. He calls two Burning Servants; interrupt his Fireball, and a priest or a shaman can remove his fire shield."] = "Un monstre rare. Il appelle deux Serviteurs ardents ; interrompez sa Boule de feu. Un prêtre ou un chaman peut dissiper son bouclier de feu.",
	["A rare. He cuts the tank's armour by three quarters, and at 15% health runs for help: finish him first."] = "Un monstre rare. Il réduit l'armure du tank des trois quarts et s'enfuit chercher de l'aide quand ses points de vie tombent à 15 % : achevez-le en priorité.",
	["A satyr on the walkway above Jergosh's chamber."] = "Un satyre sur la passerelle qui surplombe la salle de Jergosh.",
	["A slow heal (3.5 seconds) on himself or an ally. Interrupt it."] = "Un soin lent (3.5 secondes) sur lui-même ou sur un allié. Interrompez-le.",
	["A storm of dust that hits the group for about 160 to 330 nature damage. Healers, be ready for it."] = "Une tempête de poussière qui inflige au groupe environ 160 à 330 points de dégâts de Nature. Soigneurs, tenez-vous prêts.",
	["A test of the tank: he hits hard, disarms, and his Unholy Frenzy speeds his attacks by 75% for 20 seconds. Purge or dispel the frenzy, and tanks should bring a shield."] = "Un test pour le tank : il frappe fort, désarme, et sa Frénésie impie accélère ses attaques de 75 % pendant 20 secondes. Purgez ou dissipez la frénésie ; les tanks ont intérêt à porter un bouclier.",
	["A threshadon in the underwater cave; optional. He only melees."] = "Un monstre marin de la grotte sous-marine ; facultatif. Il n'attaque qu'au corps à corps.",
	["A thunder lizard in the water; killing him is optional."] = "Un lézard-tonnerre dans l'eau ; le tuer est facultatif.",
	["A titan site hidden in Un'Goro Crater, guarding secrets of the makers among the crater's dinosaurs."] = "Un site titan caché dans le cratère d'Un'Goro, qui garde les secrets des Faiseurs parmi les dinosaures du cratère.",
	["A treant twisted by fel magic, among the Suffused Treants in the streets."] = "Un tréant corrompu par la magie gangrenée, parmi les Tréants imprégnés des rues.",
	["A trogg brute on the main path; a straightforward fight if no other packs join in."] = "Une brute trogg sur le chemin principal ; un combat simple si aucun autre groupe d'ennemis ne s'en mêle.",
	["A troll city that sank into the ocean long ago has risen again, and naga, pirates and stranger things from the deep have claimed its streets."] = "Une cité troll engloutie par l'océan il y a bien longtemps a refait surface, et nagas, pirates et créatures plus étranges venues des profondeurs se sont emparés de ses rues.",
	["A vast cavern under Desolace, sacred to the centaur, where Princess Theradras, daughter of Therazane, has fouled the waters and the resting place of Zaetar."] = "Une vaste caverne sous Désolace, sacrée pour les centaures. La princesse Theradras, fille de Therazane, y a souillé les eaux et le lieu de repos de Zaetar.",
	["A ward closes his cave. Kill the two Death's Head Ward Keepers standing in front of it: the ward goes down when both are dead."] = "Une protection ferme sa grotte. Tuez les deux Gardiens de la protection Tête-de-Mort postés devant : la protection tombe quand ils sont morts tous les deux.",
	["A ward seals his cave: kill the two Death's Head Ward Keepers in front of it to bring it down."] = "Une protection scelle sa caverne : tuez les deux Gardiens de la protection Tête-de-Mort postés devant pour la briser.",
	["A way to remove a curse or cure a disease comes in handy. Otherwise an easy fight: clear the room before the pull."] = "De quoi retirer une malédiction ou guérir une maladie vous sera utile. Sinon, un combat facile : nettoyez la salle avant d'engager le combat.",
	["A white crocolisk of the marsh."] = "Un crocilisque blanc du marais.",
	["Abandoned Hope"] = "Espoir abandonné",
	["Abominable Creatures"] = "Créatures abominables",
	["Abominable Head"] = "Tête abominable",
	["About every 20 seconds he fears up to three players near him: a shaman's Tremor Totem helps. Late in the fight he enrages."] = "Environ toutes les 20 secondes, il terrifie jusqu'à trois joueurs proches : le Totem de séisme du chaman aide. En fin de combat, il devient enragé.",
	["About every 20 seconds he roars and fears up to three players near him. A shaman's Tremor Totem helps."] = "Environ toutes les 20 secondes, il rugit et terrifie jusqu'à trois joueurs proches. Le Totem de séisme du chaman aide.",
	["About one run in three, one of the graveyard's three rares stands at one of six places: Azshir the Sleepless, the Fallen Champion or Ironspine."] = "Environ une fois sur trois, l'un des trois monstres rares du cimetière se tient à l'un des six emplacements : Azshir le Sans-sommeil, le Champion déchu ou Échine-de-fer.",
	["About one run in three, one of the graveyard's three rares stands at one of the six places on the map: Azshir the Sleepless, Fallen Champion or Ironspine."] = "Environ une fois sur trois, l'un des trois monstres rares du cimetière se tient à l'un des six emplacements de la carte : Azshir le Sans-sommeil, le Champion déchu ou Échine-de-fer.",
	["Above and Beyond"] = "Au-delà du devoir",
	["Acid Splash hurts everyone near him over time. Interrupt his heal below half health; at 15% he runs for help."] = "Éclaboussure d'acide blesse peu à peu tout le monde à proximité. Interrompez ses soins sous la moitié de ses points de vie ; à 15 %, il s'enfuit chercher de l'aide.",
	["Advisor Belgrum, Dun Morogh"] = "Conseiller Belgrum, Dun Morogh",
	["Afadra Dunwall, Ironforge"] = "Afadra Dunwall, Forgefer",
	["After 60 seconds, Shadow damage to the player (2-second cast). A mage or a druid can remove it before then."] = "Au bout de 60 secondes, inflige des dégâts d'Ombre au joueur (incantation de 2 secondes). Un mage ou un druide peut le dissiper avant.",
	["After a 3-second cast, a beam comes out in front of it for 6 seconds and hits four times a second. Get out of its path as soon as the cast starts."] = "Après une incantation de 3 secondes, un rayon jaillit devant elle pendant 6 secondes et frappe quatre fois par seconde. Sortez de sa trajectoire dès le début de l'incantation.",
	["After the fight, open the room's vaults: about 24 Dwarven Heirlooms for Important Heirlooms, and the stone tablet that starts The Treaty of Understanding."] = "Après le combat, ouvrez les caveaux de la salle : environ 24 Objets de famille nains pour « Objets de famille importants », et la tablette de pierre qui lance « Le traité d'entente ».",
	["After the fight, open the vaults of the room: about 24 Dwarven Heirlooms for Important Heirlooms, and the tablet of The Treaty of Understanding."] = "Après le combat, ouvrez les caveaux de la salle : environ 24 Objets de famille nains pour « Objets de famille importants », et la tablette pour « Le traité d'entente ».",
	["Agmond's Fate"] = "Le destin d'Agmond",
	["Aku'mai's Lair"] = "Repaire d'Aku'mai",
	["Alba Fairmoon"] = "Alba Fairmoon",
	["Alba Fairmoon gives it at Sentinel Hill at the end of her chain, after a trip to Stormwind for ten Coarse Dynamite for Sprite Jumpsprocket. The forge is in the foundry, where Gilnid is fought; she then waits at the dungeon's exit with the detonator."] = "Alba Fairmoon la donne à la Colline des Sentinelles à la fin de sa suite de quêtes, après un détour par Hurlevent pour rapporter dix Dynamites grossières à Sprite Jumpsprocket. La forge se trouve dans la fonderie, là où l'on affronte Gilnid ; Alba vous attend ensuite à la sortie du donjon avec le détonateur.",
	["Alba Fairmoon, Sentinel Hill, Westfall"] = "Alba Fairmoon, Colline des Sentinelles, Marche de l'Ouest",
	["Alba Fairmoon, at the Deadmines' exit"] = "Alba Fairmoon, à la sortie des Mortemines",
	["Alba Fairmoon, at the Deadmines' exit, Westfall"] = "Alba Fairmoon, à la sortie des Mortemines, Marche de l'Ouest",
