	["Bijou's Belongings"] = "Les affaires de Bijou",
	["Bijou's Reconnaissance Report"] = "Le rapport de reconnaissance de Bijou",
	["Bijou, inside Lower Blackrock Spire"] = "Bijou, dans le pic Rochenoire inférieur",
	["Bijou, inside the dungeon"] = "Bijou, dans le donjon",
	["Blackfathom Villainy"] = "Vilenie à Brassenoire",
	["Blackhand's Command"] = "L'ordre de Main-Noire",
	["Blackrock Mountain"] = "Mont Rochenoire",
	["Blasts everyone nearby with arcane energy."] = "Inflige des dégâts d'Arcanes à tous ceux qui sont à proximité.",
	["Blood in the Streets"] = "Du sang dans les rues",
	["Blood of Morphaz"] = "Le sang de Morphaz",
	["Blood of the Black Dragon Champion"] = "Le sang du champion des dragons noirs",
	["Blood-Stained Letter"] = "Lettre tachée de sang",
	["Bloodied Insignia"] = "Insigne ensanglanté",
